#include "studio_video.h"
#include "studio_animation.h"
#include <filesystem>
#include <algorithm>
#include <chrono>
#include <cmath>
namespace studio {
namespace {
bool stamp(const std::string &path,uintmax_t &size,int64_t &modified){std::error_code ec;auto p=std::filesystem::u8path(path);if(!std::filesystem::is_regular_file(p,ec)||ec)return false;size=std::filesystem::file_size(p,ec);if(ec)return false;modified=std::filesystem::last_write_time(p,ec).time_since_epoch().count();return !ec;}
bool valid_info(const VideoInfo &i){return i.width>0&&i.height>0&&i.width<=32768&&i.height<=32768&&std::isfinite(i.fps)&&i.fps>=.01&&i.fps<=1000&&i.frame_count>0&&i.frame_count<=10000000;}
bool valid_plan(const VideoSource &s,const CapturePlan &p,std::string &error){
    if(!valid_info(s.info)||p.frames.empty()||p.frames.size()>2000||p.ticks.size()!=p.frames.size()||p.crop.x<0||p.crop.y<0||p.crop.w<1||p.crop.h<1||p.crop.x>s.info.width-p.crop.w||p.crop.y>s.info.height-p.crop.h||p.crop.w>8192||p.crop.h>8192||(size_t)p.crop.w*p.crop.h>4*1024*1024||uint64_t(p.crop.w)*p.crop.h*p.frames.size()>32*1024*1024||p.floor_x<-32768||p.floor_x>32767||p.floor_y<-32768||p.floor_y>32767){error="Choose 1–2000 frames and a crop within four million pixels / 128 MiB total RGBA. Crop the actor or choose fewer frames.";return false;}
    for(size_t i=0;i<p.frames.size();++i)if(p.frames[i]<0||p.frames[i]>=s.info.frame_count||(i&&p.frames[i]<=p.frames[i-1])||p.ticks[i]<1||p.ticks[i]>100000){error="Frame positions or holds are invalid.";return false;}return true;
}
}
bool is_video_path(const std::string &path){auto ext=std::filesystem::u8path(path).extension().u8string();for(char &c:ext)if(c>='A'&&c<='Z')c+=32;return std::set<std::string>{".mp4",".mov",".m4v",".avi",".mkv",".webm",".mpg",".mpeg",".wmv",".mts",".m2ts",".dv",".flv"}.count(ext)!=0;}
bool video_source_matches(const VideoSource &s){uintmax_t size=0;int64_t modified=0;return stamp(s.path,size,modified)&&size==s.size&&modified==s.modified;}
bool open_video_source(const std::string &path,VideoSource &out,std::string &error,const std::function<bool()> &cancelled){
    error.clear();VideoSource s;s.path=path;if(!stamp(path,s.size,s.modified)){error="Choose a readable video file.";return false;}s.ffmpeg=VideoFindFfmpeg(true);if(s.ffmpeg.empty()){error="Video capture needs ffmpeg and ffprobe. Install them on PATH or set IMGTOOL_FFMPEG to ffmpeg.";return false;}VideoProcessOptions control;control.utf8_paths=true;control.cancelled=cancelled;if(!VideoProbe(s.ffmpeg,path.c_str(),&s.info,&error,control))return false;if(!valid_info(s.info)){error="Video metadata needs usable dimensions, 0.01–1000 FPS and 1–10 million frame positions.";return false;}if(!video_source_matches(s)){error="The video changed while reading its metadata. Open it again.";return false;}out=std::move(s);return true;
}
bool plan_video_capture(const VideoSource &s,const CaptureSettings &o,CapturePlan &out,std::string &error){
    error.clear();if(!video_source_matches(s)){error="The video changed or is unavailable. Open it again before capturing.";return false;}if(!valid_info(s.info)||o.step<1||o.hold<1||o.hold>255||o.prefix.empty()||o.prefix.size()>11||std::any_of(o.prefix.begin(),o.prefix.end(),[](unsigned char c){return !((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_');})){error="Use a positive frame step/hold and a 1–11 character letters/digits/underscore prefix.";return false;}CapturePlan p;p.prefix=o.prefix;p.deinterlace=o.deinterlace;p.custom_floor=o.custom_floor;
    if(o.manual)p.frames.assign(o.picks.begin(),o.picks.end());else{if(o.first<0||o.last<o.first||o.last>=s.info.frame_count){error="Set In/Out within the video, with Out at or after In.";return false;}int n=(o.last-o.first)/o.step+1;if(n>2000){error="The range exceeds 2000 frames. Narrow In/Out or increase the frame step.";return false;}for(int i=0;i<n;++i)p.frames.push_back(o.first+i*o.step);}
    if(p.frames.empty()||p.frames.size()>2000){error="Choose 1–2000 frames to capture.";return false;}for(int f:p.frames)if(f<0||f>=s.info.frame_count){error="A picked frame is outside the video.";return false;}p.crop=o.crop;if(p.crop.w==0&&p.crop.h==0)p.crop={0,0,s.info.width,s.info.height};if(p.crop.x<0||p.crop.y<0||p.crop.w<1||p.crop.h<1||p.crop.w>s.info.width||p.crop.h>s.info.height||p.crop.x>s.info.width-p.crop.w||p.crop.y>s.info.height-p.crop.h||o.floor_x<-32768||o.floor_x>32767||o.floor_y<-32768||o.floor_y>32767){error="Use a crop inside the source and signed 16-bit floor coordinates.";return false;}p.floor_x=o.custom_floor?o.floor_x-p.crop.x:p.crop.w/2;p.floor_y=o.custom_floor?o.floor_y-p.crop.y:p.crop.h-1;
    for(size_t i=0;i<p.frames.size();++i){int ticks=o.hold;if(o.source_timing){int gap=i+1<p.frames.size()?p.frames[i+1]-p.frames[i]:std::min(i?p.frames[i]-p.frames[i-1]:o.step,(o.manual?s.info.frame_count:o.last+1)-p.frames[i]);double start=(p.frames[i]-(double)p.frames[0])*mk2_tick_hz/s.info.fps,next=start+gap*mk2_tick_hz/s.info.fps;auto hold=std::llround(next)-std::llround(start);if(hold>100000||hold<0){error="A source-time hold exceeds the supported tick range. Narrow the frame gaps.";return false;}ticks=std::max(1,(int)hold);}p.ticks.push_back(ticks);}
    if(!valid_plan(s,p,error))return false;out=std::move(p);return true;
}
bool capture_video(const VideoSource &s,const CapturePlan &p,std::vector<DigitizeSource> &out,std::string &error,const std::function<bool()> &cancelled,const std::function<void(int)> &progress){
    error.clear();if(!valid_plan(s,p,error)||!video_source_matches(s)){if(error.empty())error="The video changed before capture.";return false;}std::vector<DigitizeSource> frames;VideoDecodeOptions opt;opt.crop=p.crop;opt.deinterlace=p.deinterlace;opt.exact_crop=true;opt.max_frame_pixels=4*1024*1024;opt.first_video_stream=true;opt.process.utf8_paths=true;opt.process.cancelled=cancelled;bool mismatch=false;
    bool ok=VideoDecodeFrames(s.ffmpeg,s.path.c_str(),s.info,p.frames,opt,[&](int frame,const unsigned char *rgba,int w,int h){if(cancelled&&cancelled())return false;size_t index=frames.size();if(index>=p.frames.size()||frame!=p.frames[index]||w!=p.crop.w||h!=p.crop.h){mismatch=true;return false;}DigitizeSource f;f.label=std::filesystem::u8path(s.path).filename().u8string()+" #"+std::to_string(frame);f.w=w;f.h=h;f.ticks=p.ticks[index];f.rgba.assign(rgba,rgba+(size_t)w*h*4);frames.push_back(std::move(f));if(progress)progress((int)frames.size());return true;},&error);
    if(cancelled&&cancelled())return false;if(mismatch){error="Decoded frame dimensions or positions changed during capture.";return false;}if(!ok)return false;if(frames.size()!=p.frames.size()){error="Decoded "+std::to_string(frames.size())+" of "+std::to_string(p.frames.size())+" requested frames. Adjust Out or refresh the video metadata.";return false;}if(!video_source_matches(s)){error="The video changed during capture. Open it again.";return false;}out=std::move(frames);return true;
}
VideoJob::~VideoJob(){cancel=true;if(thread.joinable())thread.join();}
void VideoJob::start(){thread=std::thread([this]{try{auto last=std::chrono::steady_clock::now();bool timed_out=false;auto stopped=[&]{if(cancel.load())return true;if(std::chrono::steady_clock::now()-last>std::chrono::seconds(30)){timed_out=true;return true;}return false;};
        if(kind==VideoJobKind::Probe)ok=open_video_source(source.path,source,error,stopped);
        else if(kind==VideoJobKind::Capture)ok=capture_video(source,plan,frames,error,stopped,[&](int n){done=n;last=std::chrono::steady_clock::now();});
        else{if(!video_source_matches(source)){error="The video changed. Open it again.";ok=false;}else{double scale=std::min(1.,std::min(960./source.info.width,540./source.info.height));VideoDecodeOptions opt;opt.output_w=std::max(1,(int)std::lround(source.info.width*scale));opt.output_h=std::max(1,(int)std::lround(source.info.height*scale));opt.deinterlace=deinterlace;opt.max_frame_pixels=4*1024*1024;opt.first_video_stream=true;opt.process.utf8_paths=true;opt.process.cancelled=stopped;ok=VideoDecodeFrames(source.ffmpeg,source.path.c_str(),source.info,{frame},opt,[&](int,const unsigned char *rgba,int w,int h){preview_w=w;preview_h=h;preview.assign(rgba,rgba+(size_t)w*h*4);return !stopped();},&error);if(!video_source_matches(source)){ok=false;error="The video changed during preview. Open it again.";}}}
        if(timed_out&&!cancel)error="The video decoder stopped responding. Try a smaller crop or another source.";
    }catch(const std::exception &e){error=std::string("Video decoding failed: ")+e.what();ok=false;}catch(...){error="Video decoding failed.";ok=false;}finished.store(true,std::memory_order_release);});}
}
